+    <path d="M8 92 92 8" style="stroke:%23e0e0e0;stroke-width:15"/></svg>');
+}
+
+@supports (-webkit-hyphens:none) {
+    :root {
+        --underline-thickness: 0.05em;
+    }
+    :root[data-theme="theme-dark"] {
+        --underline-thickness: 0.03em;
+    }
+}
+:root[data-underline-links="on"] {
+    main a[href] {
+        text-decoration: underline var(--underline-thickness);
+        text-underline-offset: 0.14em;
+    }
+}
+:root[data-underline-links="off"] {
+    main a[href] {
+        text-decoration: none;
+    }
+}
+
+[id] {
+  scroll-margin-top: 0.9em;
+}
+
+code[id], span[id] {
+    scroll-margin-top: 0.3em;
+}
