+/*
+ * Styles for header/section anchor links
+ */
+a.anchor-link {
+    opacity: 0;
+    transition: opacity 0.1s 0.1s;
+}
+:hover > a.anchor-link {
+    opacity: 90%;
+}
+a.anchor-link:hover,
+a.anchor-link:focus-visible,
+a.anchor-link.visible {
+    opacity: 100%;
+}
+a.anchor-link > img {
+    width: 0.76em;
+    height: 0.76em;
+}
+/*
+ * Styles for theme picker
+ */
+button#theme-button {
+    position: relative;
+    width: 32px;
+    height: 32px;
+    padding: 6px;
+    margin-left: -6px;
+    background: var(--current-theme-svg) no-repeat 6px;
+    background-size: 18px 18px;
+    background-color: transparent;
+    border: 1px solid transparent;
+    border-radius: 6px;
+    cursor: pointer;
+}
+button#theme-button:hover,
+button#theme-button:focus-visible {
+    border: 1px solid var(--button-border-color);
+}
+div#theme-panel {
+    display: none;
+    position: fixed;
+    z-index: 8;
+    background-color: var(--settings-background-color);
+    color: var(--body-text-color);
+    font-size: var(--nav-font-size);
+    padding: 4px;
+    white-space: nowrap;
+    border: 1px solid var(--settings-border-color);
+    border-radius: 4px;
+    box-shadow: 0 3px 6px rgba(0,0,0,0.16), 0 3px 6px rgba(0,0,0,0.23);
+}
+button#theme-panel-close-button {
+    position: absolute;
+    right: 4px;
+    top: 4px;
+    width: 24px;
+    height: 24px;
+    background: var(--x-svg) no-repeat 5.5px;
+    background-size: 12px;
+    border: 1px solid transparent;
+    border-radius: 3px;
+    cursor: pointer;
+}
+button#theme-panel-close-button:hover,
+button#theme-panel-close-button:focus-visible {
+    border: 1px solid var(--button-border-color);
+    background-color: var(--button-hover-color);
+}
+div#theme-panel div.panel-heading {
+    font-weight: bold;
+    font-size: 16px;
+}
+div#theme-panel div {
+    padding: 10px 8px;
+}
+div#theme-panel label {
+    margin-right: 8px;
+    cursor: pointer;
+}
+div#theme-panel input {
+    margin-right: 4px;
+}
